def merge_k_sorted(lists: list[list[int]]) -> list[int]:
    if not lists:
        return None

    min_heap = []
    result = []

    # Initialize the min heap with the first element of each list
    for i, lst in enumerate(lists):
        if lst:
            heapq.heappush(min_heap, (lst[0], i, 0))

    # Extract the smallest element from the heap and add it to the result
    while min_heap:
        val, i, j = heapq.heappop(min_heap)
        result.append(val)

        # If there are more elements in the list, push the next element to the heap
        if j + 1 < len(lists[i]):
            next_val = lists[i][j + 1]
            heapq.heappush(min_heap, (next_val, i, j + 1))

    return result

