class RateLimiter:
    def __init__(self, max_calls: int, period_seconds: float):
        if max_calls <= 0 or period_seconds <= 0:
            return None

        self.max_calls = max_calls
        self.period_seconds = period_seconds
        self.tokens = 0
        self.last_reset = 0

    def allow(self, timestamp: float) -> bool:
        if timestamp <= 0:
            return None

        self._reset_tokens(timestamp)

        if self.tokens < self.max_calls:
            self.tokens += 1
            return True
        else:
            return False

    def _reset_tokens(self, timestamp: float):
        time_since_reset = timestamp - self.last_reset
        if time_since_reset > 0:
            self.tokens = min(self.tokens + int(time_since_reset / self.period_seconds * self.max_calls), self.max_calls)
            self.last_reset = timestamp

