class RateLimiter:
    def __init__(self, max_calls: int, period_seconds: float):
        if max_calls <= 0 or period_seconds <= 0:
            return None
        self.max_calls = max_calls
        self.period_seconds = period_seconds
        self.queue = deque()

    def allow(self, timestamp: float) -> bool:
        while self.queue and timestamp - self.queue[0] > self.period_seconds:
            self.queue.popleft()
        if len(self.queue) < self.max_calls:
            self.queue.append(timestamp)
            return True
        return False

