class KVStore:
    def __init__(self):
        self.store = {}

    def set(self, key: str, value, ttl: float, now: float) -> None:
        if ttl <= 0:
            return
        expiration_time = now + ttl
        self.store[key] = (value, expiration_time)

    def get(self, key: str, now: float):
        if key not in self.store:
            return None
        value, expiration_time = self.store[key]
        if now >= expiration_time:
            del self.store[key]
            return None
        return value

